{
  "description": "Inject active writing rules, gate changes, hold strict replies, and return reply feedback on the next prompt.",

  "modules": ["./register.ts"],

  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",

            "command": "cd \"${CLAUDE_PLUGIN_ROOT}\" && bun \"src/cli/main.ts\" hook",
            "timeout": 120
          }
        ]
      }
    ],

    "PreToolUse": [
      {
        "matcher": "Write|Edit|Bash",
        "hooks": [
          {
            "type": "command",

            "command": "cd \"${CLAUDE_PLUGIN_ROOT}\" && bun \"src/cli/main.ts\" hook",
            "timeout": 120
          }
        ]
      }
    ],

    "Stop": [
      {
        "hooks": [
          {
            "type": "command",

            "command": "cd \"${CLAUDE_PLUGIN_ROOT}\" && bun \"src/cli/main.ts\" hook",
            "timeout": 120
          }
        ]
      }
    ],

    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",

            "command": "cd \"${CLAUDE_PLUGIN_ROOT}\" && bun \"src/cli/main.ts\" hook",
            "timeout": 120
          }
        ]
      }
    ]
  }
}

